#include <iostream>
#include <vector>
#include <string>
#include <sstream>

class AK375 {
public:
    std::string compute(int length, const std::string& str) {
        std::stringstream tempStr2;
        std::stringstream tempStr1;
        int maxLen = 0;
        int count = 0;

        for (int i = 0; i < length; i++) {
            char c = str[i];
            if (c == '(') {
                tempStr2 << '_';
                int j = i + 1;
                while (j < length && str[j] != ')') {
                    tempStr2 << str[j];
                    j++;
                }
                i = j;
            } else if (c == ')') {
                tempStr1 << '_';
            } else {
                tempStr1 << c;
            }
        }

        std::string tempStr2Str = tempStr2.str();
        std::vector<std::string> list2;
        std::stringstream ss2(tempStr2Str);
        std::string token;
        while (std::getline(ss2, token, '_')) {
            if (!token.empty()) {
                list2.push_back(token);
            }
        }
        count = list2.size();

        std::string tempStr1Str = tempStr1.str();
        std::stringstream ss1(tempStr1Str);
        std::string p;
        while (std::getline(ss1, p, '_')) {
            if (p.length() > maxLen) {
                maxLen = p.length();
            }
        }
        return std::to_string(maxLen) + " " + std::to_string(count);
    }
};

int main() {
    AK375 solver;
    int n;
    while (std::cin >> n) {
        std::string s;
        std::cin >> s;
        std::string result = solver.compute(n, s);
        std::cout << result << std::endl;
    }
    return 0;
}

